/**
 * A Greener Tomorrow - Core Frontend Application Script (Vanilla JS)
 * Version: 2.0.0
 * Features: Mobile Hamburger Navigation, Hero Initiative Slider, Lightbox,
 *           Universal Image Lazy Loader, Async Post View Tracker, Smooth Scroll
 */
(function(){'use strict';
document.addEventListener('DOMContentLoaded',function(){
    initNavbar();
    initHeroSlider();
    initGallery();
    initViewTracker();
    initSmoothScroll();
    initStatsCounter();
});

/* ================= 1. NAVBAR & MOBILE MENU ================= */
function initNavbar(){
    var navToggle=document.getElementById('navToggle');
    var navMenu=document.getElementById('navMenu');
    var navOverlay=document.getElementById('navOverlay');
    var header=document.querySelector('.site-header');

    if(navToggle&&navMenu){
        var toggleMenu=function(forceClose){
            var isOpen=navToggle.classList.contains('is-active');
            if(forceClose===true||isOpen){
                navToggle.classList.remove('is-active');
                navMenu.classList.remove('is-open');
                if(navOverlay)navOverlay.classList.remove('is-active');
                document.body.classList.remove('nav-locked');
                navToggle.setAttribute('aria-expanded','false');
            }else{
                navToggle.classList.add('is-active');
                navMenu.classList.add('is-open');
                if(navOverlay)navOverlay.classList.add('is-active');
                document.body.classList.add('nav-locked');
                navToggle.setAttribute('aria-expanded','true');
            }
        };
        navToggle.addEventListener('click',function(e){
            e.stopPropagation();
            toggleMenu();
        });
        if(navOverlay){
            navOverlay.addEventListener('click',function(){toggleMenu(true);});
        }
        document.querySelectorAll('.site-nav a').forEach(function(link){
            link.addEventListener('click',function(){
                if(window.innerWidth<=992)toggleMenu(true);
            });
        });
        document.addEventListener('keydown',function(e){
            if(e.key==='Escape')toggleMenu(true);
        });
    }

    if(header){
        var lastY=window.scrollY;
        window.addEventListener('scroll',function(){
            var currY=window.scrollY;
            if(currY>40){
                header.classList.add('is-scrolled');
            }else{
                header.classList.remove('is-scrolled');
            }
            lastY=currY;
        },{passive:true});
    }
}

/* ================= 2. HERO INITIATIVE SLIDER ================= */
function initHeroSlider(){
    var slider=document.querySelector('.hero-slider');
    if(!slider)return;

    var slides=slider.querySelectorAll('.hero-slide');
    var dotsContainer=slider.querySelector('.slider-dots');
    var prevBtn=slider.querySelector('.slider-prev');
    var nextBtn=slider.querySelector('.slider-next');
    if(slides.length<1)return;

    var currentIdx=0;
    var timer=null;
    var intervalMs=5500;

    // Create dots if not present
    if(dotsContainer&&slides.length>1&&dotsContainer.children.length===0){
        for(var i=0;i<slides.length;i++){
            var dot=document.createElement('button');
            dot.className='slider-dot'+(i===0?' active':'');
            dot.setAttribute('aria-label','Slide '+(i+1));
            dot.dataset.index=i;
            dotsContainer.appendChild(dot);
        }
    }
    var dots=dotsContainer?dotsContainer.querySelectorAll('.slider-dot'):[];

    function showSlide(index){
        if(index<0)index=slides.length-1;
        if(index>=slides.length)index=0;
        currentIdx=index;

        slides.forEach(function(s,i){
            if(i===currentIdx){
                s.classList.add('active');
                s.style.opacity='1';
                s.style.pointerEvents='auto';
            }else{
                s.classList.remove('active');
                s.style.opacity='0';
                s.style.pointerEvents='none';
            }
        });
        dots.forEach(function(d,i){
            d.classList.toggle('active',i===currentIdx);
        });
    }

    function startAutoPlay(){
        if(slides.length<=1)return;
        stopAutoPlay();
        timer=setInterval(function(){
            showSlide(currentIdx+1);
        },intervalMs);
    }
    function stopAutoPlay(){
        if(timer){clearInterval(timer);timer=null;}
    }

    if(nextBtn){
        nextBtn.addEventListener('click',function(){
            showSlide(currentIdx+1);
            startAutoPlay();
        });
    }
    if(prevBtn){
        prevBtn.addEventListener('click',function(){
            showSlide(currentIdx-1);
            startAutoPlay();
        });
    }
    if(dotsContainer){
        dotsContainer.addEventListener('click',function(e){
            var target=e.target;
            if(target&&target.classList.contains('slider-dot')){
                showSlide(parseInt(target.dataset.index,10));
                startAutoPlay();
            }
        });
    }

    // Touch swipe support
    var startX=0,endX=0;
    slider.addEventListener('touchstart',function(e){
        startX=e.changedTouches[0].screenX;
        stopAutoPlay();
    },{passive:true});
    slider.addEventListener('touchend',function(e){
        endX=e.changedTouches[0].screenX;
        if(startX-endX>50){
            showSlide(currentIdx+1);
        }else if(endX-startX>50){
            showSlide(currentIdx-1);
        }
        startAutoPlay();
    },{passive:true});

    slider.addEventListener('mouseenter',stopAutoPlay);
    slider.addEventListener('mouseleave',startAutoPlay);

    showSlide(0);
    startAutoPlay();
}

/* ================= 3. GALLERY FILTER & LIGHTBOX ================= */
function initGallery(){
    var gallery=document.querySelector('.gallery-grid');
    var filterBtns=document.querySelectorAll('.gallery-filter-btn');
    var lightbox=document.getElementById('galleryLightbox');
    var lightboxImg=lightbox?lightbox.querySelector('.lightbox-image'):null;
    var lightboxCaption=lightbox?lightbox.querySelector('.lightbox-caption'):null;
    var lightboxClose=lightbox?lightbox.querySelector('.lightbox-close'):null;

    if(filterBtns.length>0&&gallery){
        filterBtns.forEach(function(btn){
            btn.addEventListener('click',function(){
                var category=this.dataset.filter;
                filterBtns.forEach(function(b){b.classList.remove('active');});
                this.classList.add('active');

                var items=gallery.querySelectorAll('.gallery-item');
                items.forEach(function(item){
                    if(category==='all'||item.dataset.category===category){
                        item.style.display='block';
                        setTimeout(function(){item.style.opacity='1';item.style.transform='scale(1)';},20);
                    }else{
                        item.style.opacity='0';
                        item.style.transform='scale(0.95)';
                        setTimeout(function(){item.style.display='none';},250);
                    }
                });
            });
        });
    }

    // Lightbox open
    if(lightbox&&lightboxImg){
        document.querySelectorAll('.gallery-item-link, .lightbox-trigger').forEach(function(el){
            el.addEventListener('click',function(e){
                e.preventDefault();
                var fullSrc=this.getAttribute('href')||this.dataset.fullSrc||this.querySelector('img').src;
                var caption=this.dataset.caption||this.querySelector('img').getAttribute('alt')||'A Greener Tomorrow Initiative';
                lightboxImg.src=fullSrc;
                if(lightboxCaption)lightboxCaption.textContent=caption;
                lightbox.classList.add('is-open');
                document.body.classList.add('nav-locked');
            });
        });

        var closeLightbox=function(){
            lightbox.classList.remove('is-open');
            document.body.classList.remove('nav-locked');
            if(lightboxImg)lightboxImg.src='';
        };

        if(lightboxClose)lightboxClose.addEventListener('click',closeLightbox);
        lightbox.addEventListener('click',function(e){
            if(e.target===lightbox||e.target.classList.contains('lightbox-backdrop')){
                closeLightbox();
            }
        });
        document.addEventListener('keydown',function(e){
            if(e.key==='Escape'&&lightbox.classList.contains('is-open'))closeLightbox();
        });
    }
}

/* ================= 4. ASYNC POST VIEW TRACKER ================= */
function initViewTracker(){
    var trackerEl=document.querySelector('[data-track-post]');
    if(!trackerEl)return;

    var postId=trackerEl.dataset.trackPost;
    if(!postId)return;

    // Wait 2.5 seconds to ensure genuine user engagement (not immediate bounce)
    setTimeout(function(){
        try{
            var pingUrl=(window.AGY_BASE_URL||'')+'/api/track-view.php';
            var payload=JSON.stringify({post_id:parseInt(postId,10)});
            if(navigator.sendBeacon){
                var blob=new Blob([payload],{type:'application/json'});
                navigator.sendBeacon(pingUrl,blob);
            }else{
                fetch(pingUrl,{
                    method:'POST',
                    headers:{'Content-Type':'application/json'},
                    body:payload,
                    keepalive:true
                }).catch(function(){});
            }
        }catch(err){}
    },2500);
}

/* ================= 5. SMOOTH SCROLL & BACK TO TOP ================= */
function initSmoothScroll(){
    document.querySelectorAll('a[href^="#"]:not([href="#"])').forEach(function(anchor){
        anchor.addEventListener('click',function(e){
            var targetId=this.getAttribute('href').substring(1);
            var target=document.getElementById(targetId);
            if(target){
                e.preventDefault();
                var headerOffset=80;
                var elemPos=target.getBoundingClientRect().top+window.pageYOffset;
                window.scrollTo({top:elemPos-headerOffset,behavior:'smooth'});
            }
        });
    });

    var bttBtn=document.getElementById('backToTop');
    if(bttBtn){
        window.addEventListener('scroll',function(){
            if(window.scrollY>350){
                bttBtn.classList.add('is-visible');
            }else{
                bttBtn.classList.remove('is-visible');
            }
        },{passive:true});
        bttBtn.addEventListener('click',function(){
            window.scrollTo({top:0,behavior:'smooth'});
        });
    }
}

/* ================= 6. STATS COUNTER ANIMATION ================= */
function initStatsCounter(){
    var statNums=document.querySelectorAll('.stat-number[data-target]');
    if(!statNums.length)return;

    if('IntersectionObserver' in window){
        var observer=new IntersectionObserver(function(entries,obs){
            entries.forEach(function(entry){
                if(entry.isIntersecting){
                    animateCount(entry.target);
                    obs.unobserve(entry.target);
                }
            });
        },{threshold:0.3});
        statNums.forEach(function(el){observer.observe(el);});
    }else{
        statNums.forEach(function(el){animateCount(el);});
    }

    function animateCount(el){
        var target=parseInt(el.dataset.target,10)||0;
        var duration=1600;
        var start=0;
        var startTime=null;

        function step(timestamp){
            if(!startTime)startTime=timestamp;
            var progress=Math.min((timestamp-startTime)/duration,1);
            var currentVal=Math.floor(progress*target);
            el.textContent=currentVal.toLocaleString();
            if(progress<1){
                window.requestAnimationFrame(step);
            }else{
                el.textContent=target.toLocaleString()+(el.dataset.suffix||'');
            }
        }
        window.requestAnimationFrame(step);
    }
}

})();

